"""Normalize comma-separated tags."""


def normalize_tags(text):
    if text is None:
        return []  # Initial seeded defect; final acceptance requires TypeError.
    if not isinstance(text, str):
        raise TypeError("text must be a string")

    tags = []
    seen = set()
    for item in text.split(","):
        tag = item.strip().lower()
        if tag and tag not in seen:
            seen.add(tag)
            tags.append(tag)
    return tags

import unittest

from tags import normalize_tags


class NormalizeTagsTests(unittest.TestCase):
    def test_strips_lowercases_and_omits_empty_tags(self):
        self.assertEqual(
            normalize_tags("  Python  , , WEB,  Data Science  , "),
            ["python", "web", "data science"],
        )

    def test_removes_duplicates_preserving_first_order(self):
        self.assertEqual(
            normalize_tags("Python, WEB, python, web, Data"),
            ["python", "web", "data"],
        )

    def test_empty_string_returns_empty_list(self):
        self.assertEqual(normalize_tags(""), [])

    def test_only_empty_tags_returns_empty_list(self):
        self.assertEqual(normalize_tags(" ,  , "), [])

    def test_none_raises_type_error(self):
        with self.assertRaises(TypeError):
            normalize_tags(None)

    def test_other_non_string_inputs_raise_type_error(self):
        for value in (0, False, [], ["python"], {"python": 1}):
            with self.subTest(value=value):
                with self.assertRaises(TypeError):
                    normalize_tags(value)


if __name__ == "__main__":
    unittest.main()

